import pulp

prob = pulp.LpProblem("RealEstate", pulp.LpMaximize)
x = {i: pulp.LpVariable(f"x{i}", cat="Binary") for i in range(1, 5)}

income = {1: 12500, 2: 35000, 3: 23000, 4: 100000}
cost = {1: 1.5e6, 2: 2.1e6, 3: 2.3e6, 4: 4.2e6}

prob += pulp.lpSum(income[i] * x[i] for i in x)
prob += pulp.lpSum(cost[i] * x[i] for i in x) <= 7e6
prob += x[4] + x[3] <= 1

prob.solve(pulp.PULP_CBC_CMD(msg=False, timeLimit=60))
print(f"STATUS={pulp.LpStatus[prob.status]} OBJECTIVE={pulp.value(prob.objective)}")

