import pulp, math

areas = [1, 2, 3, 4]
dist = {1: 450, 2: 480, 3: 540, 4: 600}
ph = {1: 0.10, 2: 0.20, 3: 0.15, 4: 0.25}
pl = {1: 0.08, 2: 0.16, 3: 0.12, 4: 0.20}

# fuel per mission (round trip: loaded out, empty back) + 100 takeoff/landing
fh = {i: 100 + dist[i]/2 + dist[i]/4 for i in areas}
fl = {i: 100 + dist[i]/3 + dist[i]/4 for i in areas}

# linearized objective: minimize sum x*(-ln(1-p)); success prob = 1 - exp(-obj)
ch = {i: -math.log(1 - ph[i]) for i in areas}
cl = {i: -math.log(1 - pl[i]) for i in areas}

prob = pulp.LpProblem("bombing", pulp.LpMinimize)
xh = {(i): pulp.LpVariable(f"xh{i}", lowBound=0, cat="Integer") for i in areas}
xl = {(i): pulp.LpVariable(f"xl{i}", lowBound=0, cat="Integer") for i in areas}

prob += pulp.lpSum(ch[i]*xh[i] + cl[i]*xl[i] for i in areas)

prob += pulp.lpSum(fh[i]*xh[i] + fl[i]*xl[i] for i in areas) <= 48000
prob += pulp.lpSum(xh[i] for i in areas) <= 48
prob += pulp.lpSum(xl[i] for i in areas) <= 32

prob.solve(pulp.PULP_CBC_CMD(msg=False, timeLimit=60))
print(f"STATUS={pulp.LpStatus[prob.status]} OBJECTIVE={pulp.value(prob.objective)}")
