products = [1, 2, 3]
machines = [1, 2, 3]
positions = [1, 2, 3]

prob = pulp.LpProblem("flow_shop", pulp.LpMinimize)

y = pulp.LpVariable.dicts("y", (products, positions), cat="Binary")
s = pulp.LpVariable.dicts("s", (machines, positions), lowBound=0)
Cmax = pulp.LpVariable("Cmax", lowBound=0)

prob += Cmax

for k in positions:
    prob += pulp.lpSum(y[i][k] for i in products) == 1
for i in products:
    prob += pulp.lpSum(y[i][k] for k in positions) == 1

def p(j, k):
    return pulp.lpSum(t[i][j] * y[i][k] for i in products)

for j in machines:
    for k in positions:
        if k > 1:
            prob += s[j][k] >= s[j][k-1] + p(j, k-1)
for k in positions:
    for j in machines[:-1]:
        prob += s[j+1][k] >= s[j][k] + p(j, k)

prob += Cmax >= s[3][3] + p(3, 3)

prob.solve(pulp.PULP_CBC_CMD(msg=False, timeLimit=60))
print(f"STATUS={pulp.LpStatus[prob.status]} OBJECTIVE={pulp.value(prob.objective)}")
