import pulp

trains = ["G1","G3","G5","G7","G9","G11","G13","G15","G17","G19","G21","G23","G25","G27","G29","G31"]
speed = {t:(350 if i<6 else 300) for i,t in enumerate(trains)}
planned = {t: 8*i for i,t in enumerate(trains)}   # planned arrival at station boundary (min)
tracks = ["I","II","III","IV","V"]
btime = {"I":4,"II":4,"III":4,"IV":5,"V":5}
paths = [1,2,3,4,5,6,7]
path_track = {1:"I",2:"I",3:"II",4:"III",5:"IV",6:"IV",7:"V"}
conflict = {1:{2,3,4,5,6,7},2:{1,3,4,5,6,7},3:{1,2,4,5,6,7},4:{1,2,3,5,6,7},
            5:{1,2,3,4,6,7},6:{1,2,3,4,5,7},7:{1,2,3,4,5,6}}
DWELL = 20; HEAD = 3; M = 10000

prob = pulp.LpProblem("station_A", pulp.LpMinimize)
a = {i: pulp.LpVariable(f"a_{i}", lowBound=planned[i]) for i in trains}
d = {i: pulp.LpVariable(f"d_{i}", lowBound=0) for i in trains}
x = {(i,t): pulp.LpVariable(f"x_{i}_{t}", cat="Binary") for i in trains for t in tracks}
y = {(i,p): pulp.LpVariable(f"y_{i}_{p}", cat="Binary") for i in trains for p in paths}
z = {(i,j): pulp.LpVariable(f"z_{i}_{j}", cat="Binary") for ii,i in enumerate(trains) for j in trains[ii+1:]}

for i in trains:
    prob += pulp.lpSum(x[i,t] for t in tracks) == 1
    prob += pulp.lpSum(y[i,p] for p in paths) == 1
    for p in paths:
        prob += x[i, path_track[p]] >= y[i,p]
    prob += d[i] == a[i] + DWELL

# same-track separation (full occupancy interval)
for ii,i in enumerate(trains):
    for j in trains[ii+1:]:
        for t in tracks:
            prob += a[j] >= d[i] + HEAD - M*(2 - x[i,t] - x[j,t] - z[i,j])
            prob += a[i] >= d[j] + HEAD - M*(2 - x[i,t] - x[j,t] + z[i,j])
        # conflicting approach paths (arrival instants)
        for p in paths:
            for q in conflict[p]:
                prob += a[j] >= a[i] + HEAD - M*(3 - y[i,p] - y[j,q] - z[i,j])
                prob += a[i] >= a[j] + HEAD - M*(3 - y[i,p] - y[j,q] + z[i,j])

prob += pulp.lpSum(d[i] + btime[path_track[p]] * y[i,p] for i in trains for p in paths)

prob.solve(pulp.PULP_CBC_CMD(msg=False, timeLimit=60))

print("=== Train timetable at Station A (min) ===")
for i in trains:
    t = next(t for t in tracks if x[i,t].value() > 0.5)
    p = next(p for p in paths if y[i,p].value() > 0.5)
    print(f"train {i}: arrive={a[i].value():.0f} depart={d[i].value():.0f} track={t} path={p} exit_boundary={d[i].value()+btime[t]:.0f}")
print("=== Station A arrival/departure board ===")
for i in sorted(trains, key=lambda k: a[k].value()):
    print(f"{i}: arrival {a[i].value():.0f}, departure {d[i].value():.0f}")
print(f"STATUS={pulp.LpStatus[prob.status]} OBJECTIVE={pulp.value(prob.objective)}")
