import pulp

products = ["A1", "A2", "A3"]
months = ["Jan", "Feb", "Mar", "Apr"]
days = {"Jan": 23, "Feb": 20, "Mar": 23, "Apr": 22}
demand = {
    "A1": [5300, 1200, 7400, 5300],
    "A2": [4500, 5400, 6500, 7200],
    "A3": [4400, 6700, 12500, 13200],
}
price = {"A1": 124, "A2": 109, "A3": 115}
cost = {"A1": 73.30, "A2": 52.90, "A3": 65.40}
quota = {"A1": 500, "A2": 450, "A3": 550}
activation = {"A1": 150000, "A2": 150000, "A3": 100000}
minbatch = {"A1": 20, "A2": 20, "A3": 16}
store_cost = {"A1": 3.50, "A2": 4.00, "A3": 3.00}
cap = 800

prob = pulp.LpProblem("production", pulp.LpMaximize)
x = {(i, t): pulp.LpVariable(f"x_{i}_{t}", lowBound=0) for i in products for t in months}
y = {(i, t): pulp.LpVariable(f"y_{i}_{t}", cat="Binary") for i in products for t in months}
s = {(i, t): pulp.LpVariable(f"s_{i}_{t}", lowBound=0) for i in products for t in months}

for i in products:
    for k, t in enumerate(months):
        prob += x[i, t] <= quota[i] * days[t] * y[i, t]
        prob += x[i, t] >= minbatch[i] * y[i, t]
        prev = s[i, months[k - 1]] if k > 0 else 0
        prob += prev + x[i, t] - demand[i][k] == s[i, t]
        prob += s[i, t] <= cap

prob += (
    pulp.lpSum(price[i] * demand[i][k] for i in products for k in range(4))
    - pulp.lpSum(cost[i] * x[i, t] for i in products for t in months)
    - pulp.lpSum(activation[i] * y[i, t] for i in products for t in months)
    - pulp.lpSum(store_cost[i] * s[i, t] for i in products for t in months)
)

prob.solve(pulp.PULP_CBC_CMD(msg=False, timeLimit=60))
print(f"STATUS={pulp.LpStatus[prob.status]} OBJECTIVE={pulp.value(prob.objective)}")
