import pulp

n = 7
dist = {
    (1,2):86,(1,3):49,(1,4):57,(1,5):31,(1,6):69,(1,7):50,
    (2,3):68,(2,4):79,(2,5):93,(2,6):24,(2,7):5,
    (3,4):16,(3,5):7,(3,6):72,(3,7):67,
    (4,5):90,(4,6):69,(4,7):1,
    (5,6):86,(5,7):59,
    (6,7):81,
}
c = {}
for (i,j),d in dist.items():
    c[(i,j)] = d
    c[(j,i)] = d

prob = pulp.LpProblem("TSP", pulp.LpMinimize)
x = pulp.LpVariable.dicts("x", [(i,j) for i in range(1,n+1) for j in range(1,n+1) if i!=j], cat="Binary")
u = pulp.LpVariable.dicts("u", range(2,n+1), lowBound=1, upBound=n-1)

prob += pulp.lpSum(c[(i,j)]*x[(i,j)] for i in range(1,n+1) for j in range(1,n+1) if i!=j)

for j in range(1,n+1):
    prob += pulp.lpSum(x[(i,j)] for i in range(1,n+1) if i!=j) == 1
for i in range(1,n+1):
    prob += pulp.lpSum(x[(i,j)] for j in range(1,n+1) if j!=i) == 1

# MTZ subtour elimination
for i in range(2,n+1):
    for j in range(2,n+1):
